const rows=$input.all().map(item=>item.json);
const evidenceRows=rows.filter(row=>row.product_name);
const evidenceByOpportunity=new Map();
const evidenceByName=new Map();
for(const row of evidenceRows){ const sourceProblem=String(row.product_name || ''); const searchQuery=String(row.search_query || ''); const opportunityId=String(row.opportunity_id || (row.source_id ? 'reddit:' + row.source_id : 'legacy:' + sourceProblem.toLowerCase() + '|' + searchQuery.toLowerCase())); const evidence={opportunity_id:opportunityId,source_id:row.source_id || null,source_url:row.source_url || null,source_problem:sourceProblem,search_query:searchQuery,problem_evidence:row.trend_context || null,problem_code:row.problem_solved || null,target_customer:row.target_customer || null,why_relevant:row.why_relevant || null}; evidenceByOpportunity.set(opportunityId,evidence); if(!evidenceByName.has(sourceProblem)) evidenceByName.set(sourceProblem,evidence); }
const pendingStatuses=new Set(['RESEARCHED','PHASE3_RETRY']);
const seen=new Set(); const output=[]; const now=Date.now();
for(const row of rows.filter(row=>row['product name'] && pendingStatuses.has(String(row.status || '').toUpperCase()))){ const status=String(row.status || '').toUpperCase(); const nextRetry=Date.parse(String(row.phase3_next_retry_at || '')); if(status==='PHASE3_RETRY' && Number.isFinite(nextRetry) && nextRetry>now) continue; const link=String(row.link || ''); const productId=String(row.product_id || link.match(/(?:item\/|\b)(\d{10,})(?:\.html)?/)?.[1] || ''); const sourceProblem=String(row['product name'] || ''); const opportunityId=String(row.opportunity_id || ''); const evidence=evidenceByOpportunity.get(opportunityId) || evidenceByName.get(sourceProblem); if(!productId || !evidence) continue; const destination=String(row.destination_country || 'FR').toUpperCase(); const key=String(row.evaluation_key || evidence.opportunity_id+'|'+productId+'|'+destination); if(seen.has(key)) continue; seen.add(key); output.push({json:{...row,...evidence,product_id:productId,destination_country:destination,evaluation_key:key,phase3_retry_count:Number(row.phase3_retry_count || 0)}}); }
return output.slice(0,50);

const details=$input.all(); const sources=$('Join evidence and select up to 50 products').all(); const products=details.map((item,index)=>{ const p=item.json; const source=sources[index]?.json || {}; const supplier=p.supplier || {}; const variants=(p.variants || []).filter(v=>v.eligible_for_destination !== false).slice(0,5).map(v=>({label:v.label,attributes:v.attributes,sale_price:v.sale_price,currency:v.currency,stock:v.stock,available:v.available,eligible_for_destination:v.eligible_for_destination})); return {product_id:p.product_id,opportunity_id:source.opportunity_id || null,source_id:source.source_id || null,source_url:source.source_url || null,destination_country:source.destination_country || 'FR',evaluation_key:source.evaluation_key,phase3_retry_count:Number(source.phase3_retry_count || 0),source_problem:source.source_problem,search_query:source.search_query,problem_evidence:source.problem_evidence,problem_code:source.problem_code,target_customer:source.target_customer,why_relevant:source.why_relevant,title:p.title,url:p.url,currency:p.currency,eligible_min_price:p.eligible_min_price,eligible_max_price:p.eligible_max_price,eligible_variant_count:p.eligible_variant_count,rating:p.rating,review_count:p.review_count,orders_count:p.orders_count,supplier:{name:supplier.name,positive_feedback:supplier.positive_feedback,followers:supplier.followers,years_open:supplier.years_open,top_rated:supplier.top_rated},variant_examples:variants,warnings:p.warnings || [],snapshot_status:p.last_status,field_fetched_at:p.field_fetched_at || {},specifications:p.specifications || {}}; });
const grouped=new Map(); for(const p of products){ if(!grouped.has(p.opportunity_id)) grouped.set(p.opportunity_id,[]); grouped.get(p.opportunity_id).push(p); }
const batches=[]; let batchId=1; for(const [opportunityId,items] of grouped){ for(let i=0;i<items.length;i+=5) batches.push({json:{batch_id:batchId++,opportunity_id:opportunityId,source_problem:items[0]?.source_problem,products:items.slice(i,i+5),prompt_version:'product-evaluator-strict-v3'}}); } return batches;

const responses=$input.all();
const batches=$('Build evidence batches of 5').all();
if(responses.length !== batches.length) throw new Error(`Expected ${batches.length} AI responses, got ${responses.length}`);
const scoreFields=['problem_solution_fit','evidence_quality','supplier_signal','variant_fit','marketing_potential','return_risk','overall_score','confidence'];
const allowedReasons=new Set(['DIRECT_FIT','PLAUSIBLE_NEEDS_CHECK','DIMENSIONS_UNPROVEN','PRODUCT_TYPE_MISMATCH','WEAK_EVIDENCE','NO_ELIGIBLE_VARIANT','SUPPLIER_EVIDENCE_WEAK','HIGH_RETURN_RISK']);
return responses.flatMap((item,index)=>{
  const batch=batches[index].json;
  const raw=String(item.json.text || '').replace(/```json/gi,'').replace(/```/g,'').trim();
  const byProduct=new Map(batch.products.map(p=>[String(p.product_id),p]));
  let parsedResults=[]; let batchError=null;
  try {
    const parsed=JSON.parse(raw);
    parsedResults=Array.isArray(parsed)?parsed:parsed.results;
    if(!Array.isArray(parsedResults)) throw new Error('results is not an array');
  } catch(error) { batchError=error.message; }
  const byId=new Map();
  if(!batchError){
    for(const result of parsedResults){
      const id=String(result?.product_id || '');
      if(!byProduct.has(id)){ batchError='Unknown product_id: '+id; break; }
      if(byId.has(id)){ batchError='Duplicate product_id: '+id; break; }
      byId.set(id,result);
    }
  }
  const metadata=item.json.response_metadata || item.json.usage_metadata || item.json.usage || null;
  return batch.products.map(product=>{
    const original=byId.get(String(product.product_id));
    const errors=[];
    if(batchError) errors.push(batchError);
    if(!original) errors.push('AI omitted this product');
    if(original){
      const verdict=String(original.verdict || '').toLowerCase();
      if(!['shortlist','hold','reject'].includes(verdict)) errors.push('Invalid verdict');
      if(!allowedReasons.has(String(original.reason_code || ''))) errors.push('Invalid reason_code');
      if(!String(original.reasoning_short || '').trim()) errors.push('Missing reasoning_short');
      for(const field of scoreFields){ const value=original[field]; if(typeof value!=='number' || !Number.isFinite(value) || !Number.isInteger(value) || value<0 || value>100) errors.push('Invalid '+field); }
    }
    let result;
    if(errors.length){
      result={product_id:product.product_id,verdict:'hold',reason_code:'AI_FORMAT_ERROR',problem_solution_fit:0,evidence_quality:0,supplier_signal:0,variant_fit:0,marketing_potential:0,return_risk:0,overall_score:0,positive_evidence:[],risks:[],next_validation_steps:['Rerun evaluation'],reasoning_short:'Invalid AI result: '+errors.join('; '),confidence:0};
    } else {
      result={...original,verdict:String(original.verdict).toLowerCase()};
      if(Number(product.eligible_variant_count || 0)<=0){ result.verdict='reject'; result.reason_code='NO_ELIGIBLE_VARIANT'; }
      if(result.verdict==='shortlist' && (result.overall_score<75 || result.problem_solution_fit<80 || result.evidence_quality<65 || result.variant_fit<70)) result.verdict='hold';
      if(result.verdict==='hold' && result.overall_score>=75){ result.verdict='hold'; result.overall_score=74; }
    }
    const formatError=errors.length?errors.join('; '):null;
    return {json:{...result,source_product:product.source_problem,opportunity_id:product.opportunity_id || null,source_id:product.source_id || null,source_url:product.source_url || null,destination_country:product.destination_country || 'FR',evaluation_key:product.evaluation_key || (product.source_problem+'|'+product.product_id+'|FR'),phase3_retry_count:Number(product.phase3_retry_count || 0),product_name:product.title,product_url:product.url,search_query:product.search_query,batch_id:batch.batch_id,prompt_version:'product-evaluator-strict-v3',format_error:formatError,model_metadata:metadata,raw_response_chars:raw.length}};
  });
});
